import{_ as t,o,c as a,ak as n}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Browser extension","description":"","frontmatter":{"title":"Browser extension","lang":"en-US"},"headers":[],"relativePath":"extension.md","filePath":"extension.md","lastUpdated":1787121368000}'),s={name:"extension.md"};function r(i,e,c,d,h,l){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="browser-extension" tabindex="-1">Browser extension <a class="header-anchor" href="#browser-extension" aria-label="Permalink to &quot;Browser extension&quot;">​</a></h1><p>Piwi Picker is a Chrome/Edge extension (Manifest V3) that picks ranked, stable Playwright locators directly from the page you&#39;re looking at — scored by the same engine the dashboard uses, and can record a multi-page flow into a runnable TypeScript spec. Picking and recording are fully standalone — nothing is sent anywhere by default. Connecting to a Piwi instance is optional and adds exactly one thing: matching a recording against your project&#39;s own page-object methods and helpers, ranked live as you record.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p><strong><a href="https://chromewebstore.google.com/detail/piwi-picker/pakhnokpjboejcghgcmkjlpnogfjihhe" target="_blank" rel="noreferrer">Piwi Picker on the Chrome Web Store ↗</a></strong> — click <strong>Add to Chrome</strong> and you&#39;re done; updates arrive from the store like any other extension.</p><p>That one listing covers <strong>Edge too</strong>, and every other Chromium browser (Brave, Vivaldi, Opera). Edge blocks other stores until you say otherwise: the first Chrome Web Store page you open in it shows an <strong>Allow extensions from other stores</strong> banner — click <strong>Allow</strong> once, and <strong>Get</strong> installs and auto-updates exactly as it does in Chrome. There&#39;s no separate Edge Add-ons listing yet.</p><h3 id="from-source" tabindex="-1">From source <a class="header-anchor" href="#from-source" aria-label="Permalink to &quot;From source&quot;">​</a></h3><p>Only needed if you want an unreleased build, or you&#39;re changing the extension itself.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/PiwiTests/platform.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> platform</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extension:build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=apps/extension</span></span></code></pre></div><p>Then, in Chrome or Edge:</p><ol><li>Open <code>chrome://extensions</code> (<code>edge://extensions</code> on Edge).</li><li>Turn on <strong>Developer mode</strong>.</li><li><strong>Load unpacked</strong> → select <code>apps/extension/dist</code>.</li></ol><p>A source build doesn&#39;t auto-update — rebuild and reload its card on the extensions page to pick up changes. If you already have the store version installed, disable one or the other so two copies of the picker don&#39;t both bind the keyboard shortcut.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Every action in the toolbar popup has a digit shortcut, shown on its tile and numbered in reading order: <code>1</code> records, <code>2</code> picks an element, through to <code>0</code> for <strong>Test functions</strong>. With the popup open, press the digit instead of clicking.</p><p>Only one tool runs at a time: starting one closes whatever was open, and the popup marks the running tool as <strong>running</strong> so you can see what is live on the page. <strong>Esc</strong> cancels it from anywhere. Recording is the exception — it is a capture mode rather than a momentary tool, so it keeps running while you use the others, and only its own <strong>Stop</strong> ends it.</p><p>Picking also has a shortcut that works <em>without</em> opening the popup, suggested as <code>Ctrl+Shift+E</code> (<code>Cmd+Shift+E</code> on macOS). A browser only assigns a suggested key when it is free, so if another extension already holds that combination — or you&#39;re on Firefox, where <code>Ctrl+Shift+E</code> opens the built-in Network Monitor — it stays unbound and pressing it does nothing. The popup footer reports the key actually bound, and offers a link to <code>chrome://extensions/shortcuts</code> to assign one when there is none.</p><ul><li><strong>Pick an element</strong> — click the toolbar icon → <strong>Pick an element</strong>, or press <code>Ctrl+Shift+E</code> (<code>Cmd+Shift+E</code> on macOS) on any page. Hover highlights, a click picks — the pick snaps to the nearest actionable ancestor (a click on the text inside a button picks the button), and ↑/↓ walk the DOM tree before it commits. The locator the hovered element would produce is shown as you move: syntax-highlighted in a chip pinned to the element, and again on its own line in the picker banner, so ↑/↓ walking shows what each step in the tree is worth. When the element has a role, an <strong>anchors</strong> step follows: bless one or more stable parent elements to scope the locator to, with a live &quot;matches N&quot; count.</li><li><strong>Ranked locators, re-checked live</strong> — every candidate is scored the way the dashboard scores captured locators, then re-counted against the page as it is right now (a page can re-render between the pick and reviewing the results). A candidate that&#39;s become ambiguous is shown with its current match count and a suggestion to add <code>.first()</code> or <code>.filter({ hasText: … })</code> — never silently dropped. A locator that matches more than one element is ranked <em>below</em> every candidate known to resolve to exactly one, so a parent-scoped chain like <code>getByTestId(&#39;product-43&#39;).getByRole(&#39;button&#39;)</code> comes out on top of a bare <code>getByRole(&#39;button&#39;, { name: &#39;Add to cart&#39; })</code> that hits every card on the page. Parents are anchored on whatever hook they actually carry — <code>data-testid</code>, <code>id</code>, a landmark role, or an app-specific <code>data-*</code> such as <code>data-product=&quot;43&quot;</code> or <code>data-row-id=&quot;7&quot;</code> — so a repeated card identified only by a <code>data-*</code> attribute still gets a chain (<code>locator(&#39;[data-product=&quot;43&quot;]&#39;).getByRole(&#39;button&#39;)</code>). Framework bookkeeping (<code>data-v-4f2a1b</code>, <code>data-reactid</code>, Svelte/Angular/Ember instance ids) is skipped, as are valueless markers. An element with no role at all — a price <code>&lt;span&gt;</code>, a status badge — is scoped the same way through its text (<code>getByTestId(&#39;row-keyboard&#39;).getByText(&#39;£49.99&#39;)</code>), so a repeated value is still addressable; when the text is already unique on the page the plain <code>getByText</code> stays on top and the chain is just the fallback below it. And when the page carries no hooks at all — a cart list, a results table — the repeated container is singled out by the text that names it: <code>getByRole(&#39;listitem&#39;).filter({ hasText: &#39;Keyboard&#39; }).getByRole(&#39;button&#39;)</code>. The filter text is the row&#39;s heading where it has one, never the text of the element you picked (filtering on that narrows nothing), and it is only offered when it leaves exactly one container matching.</li><li><strong>Copy in three forms</strong> — the bare locator, a full action line (<code>await page.getByRole(…).click();</code>), or a visibility assertion (<code>await expect(page.getByRole(…)).toBeVisible();</code>). Your last-used form is remembered for next time.</li><li><strong>Hover-inspect</strong> — toggle from the popup: hover any element to see its best-ranked locator in a syntax-highlighted tooltip, no click needed.</li><li><strong>Locator console</strong> — type or paste a locator expression (a safe subset — <code>getBy*</code> chains, <code>locator(css)</code>, <code>filter({ hasText })</code>, <code>.first()</code>/<code>.last()</code>/<code>.nth()</code> — parsed, never <code>eval</code>&#39;d) and see every match highlighted on the page live, with a strict-mode verdict and count. The outlines carry the verdict: green for the single match that passes strict mode, amber and numbered for each of several.</li><li><strong>Multi-pick pattern derivation</strong> — pick 2–3 similar items (table rows, cards) and derive the shared list pattern (e.g. <code>getByRole(&#39;row&#39;).filter({ hasText: … })</code>), with a warning when only index-based (<code>.nth()</code>) discrimination was possible.</li><li><strong>Lint overlay</strong> — one click outlines every interactive element on the page that would score badly as a locator target right now (no test id, no accessible name, no stable structural anchor), with a suggested <code>data-testid</code> per element and a one-click Markdown checklist export.</li><li><strong>Assertion suggester</strong> — pick an element and get ranked <code>expect(...)</code> candidates built against its top-ranked locator — whichever of <code>toHaveValue</code>, <code>toHaveText</code>, <code>toHaveAccessibleName</code>, and <code>toBeVisible</code> actually apply to it — with a one-click copy per candidate.</li><li><strong>Session</strong> — pick and name elements as you browse, even across different pages, then export the whole named list as a Playwright POM-style fixture class, a Markdown table (paste into a PR description or issue), or JSON. The session lives for as long as the browser stays open — see <a href="#permissions-explained">Permissions</a>.</li><li><strong>Copy context for agent</strong> — pick an element and copy one paste-able block for an AI coding agent: the page URL, a compact element summary (tag, role, accessible name, key attributes, text), and every ranked locator alternative.</li><li><strong>Record actions across pages</strong> — click <strong>Record actions</strong> and Piwi Picker grants itself access to the one site you&#39;re on, then captures clicks, fills, checks/unchecks, select changes, and Enter-to-submit as you browse — across as many pages on that site as you like. A red border around the page marks the tab as being recorded, and a small HUD tracks the step count and shows the top-ranked locator for whatever you just interacted with. Click <strong>Stop</strong> to open the review panel: check the captured steps, then <strong>Copy as TypeScript</strong> for a runnable Playwright spec (<code>page.goto</code>, then one line per step), or <strong>Discard</strong> to throw the recording away. Password fields are never captured — their value is replaced with a <code>process.env.*</code> placeholder in the generated code.</li><li><strong>Matching functions, ranked live</strong> <em>(needs a Piwi connection)</em> — connect to a Piwi instance from the toolbar popup&#39;s config (gear) button, map one or more URL patterns to a project (wildcards allowed, e.g. <code>https://shop.example.com/**</code>), and the recorder fetches each mapped project&#39;s function catalog — page-object methods and helpers it already knows about. Which project applies on a given page is resolved automatically from that mapping (first match wins), or you can override it for the current tab from the popup&#39;s <strong>Active project</strong> select. While recording, the HUD ranks which catalog function the steps so far look like, live, with a progress indicator (<code>2/3</code>) until a full match is found. On export, any complete match collapses into a call to your own function instead of raw locator lines; anything unmatched still comes out as plain locators. The matcher only ever <em>selects among</em> the catalog you&#39;ve registered — it never invents a function. Manage the catalog from a project&#39;s <strong>Test functions</strong> page in the dashboard.</li><li><strong>Test functions against this page</strong> <em>(needs a Piwi connection)</em> — click <strong>Test functions</strong> in the popup for a checklist of every function in the active project&#39;s catalog, scored against the page you&#39;re on right now: which pattern steps resolve to exactly one element (<strong>ready to use here</strong>), which are ambiguous or missing (<strong>partial match</strong>), and which don&#39;t apply here at all (<strong>not found on this page</strong>) — no recording or replay needed, just a live read of the current DOM against each function&#39;s stored pattern. A <strong>Manage catalog in Piwi ↗</strong> link in the panel header opens that project&#39;s <strong>Test functions</strong> page in a new tab.</li></ul><h2 id="permissions-explained" tabindex="-1">Permissions, explained <a class="header-anchor" href="#permissions-explained" aria-label="Permalink to &quot;Permissions, explained&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Why</th></tr></thead><tbody><tr><td><code>activeTab</code></td><td>Lets the extension act on the tab you&#39;re looking at only when you click the toolbar icon or press the keyboard shortcut — not on every page you visit.</td></tr><tr><td><code>scripting</code></td><td>Injects the picker (and the recorder) into the active tab on demand — there is no background content script running on pages you haven&#39;t asked it to.</td></tr><tr><td><code>storage</code></td><td>Remembers your last-used copy format, a named pick session, the running recording, and (only if you connect) the instance URL/API key, the URL-pattern → project mappings, and each mapped project&#39;s cached function catalog — all locally on your machine. Pick sessions, the recording, and a manual <strong>Active project</strong> override specifically use <code>chrome.storage.session</code>, which the browser clears when you close it — a working session, not a saved file.</td></tr><tr><td><code>optional_host_permissions</code> (<code>http://*/*</code>, <code>https://*/*</code>, granted nothing by default)</td><td>Recording across pages needs to keep working after you navigate, which <code>activeTab</code> alone can&#39;t do (it&#39;s revoked on navigation). Clicking <strong>Record actions</strong> requests access to <em>the one site you&#39;re on</em> — never <code>&lt;all_urls&gt;</code>, never granted in advance — so the recorder can re-attach itself as you move between that site&#39;s pages. The other use is your own Piwi instance&#39;s origin, requested when you save the connection settings — the extension needs it to read your function catalog, and to keep that catalog up to date afterwards. Both are single origins you pick, never <code>&lt;all_urls&gt;</code>.</td></tr></tbody></table><p>No picking, hover-inspect, locator console, multi-pick, lint overlay, assertion suggester, session export, agent-context copy, or standalone recording ever reaches a network. Connecting to a Piwi instance is the one opt-in exception — see below.</p><h2 id="connecting-to-a-piwi-instance" tabindex="-1">Connecting to a Piwi instance <a class="header-anchor" href="#connecting-to-a-piwi-instance" aria-label="Permalink to &quot;Connecting to a Piwi instance&quot;">​</a></h2><p>Entirely optional, and off by default. From the toolbar popup, the config (gear) button opens a settings page for your instance&#39;s URL and an API key (<code>pd_…</code>, from your account&#39;s API key settings). Below that is a <strong>Project mappings</strong> table: rows of a URL pattern (wildcards allowed — <code>*</code> matches within one path segment, <code>**</code> crosses segments, e.g. <code>https://shop.example.com/**</code>) and the project it maps to. Saving fetches every mapped project&#39;s function catalog and caches it on your machine — nothing about your browsing is sent in that request beyond each project&#39;s id. Saving also asks for access to your instance&#39;s origin: the extension needs it to reach the API, and without it the catalog can&#39;t refresh on its own afterwards.</p><p>The cache keeps itself current, so functions you add in the dashboard show up without reconnecting: opening <strong>Test functions</strong> shows the cached catalog immediately and re-fetches in the background, and its <strong>Refresh</strong> button forces an immediate re-fetch. A recording refreshes once per page rather than per step, and again when you stop, so <strong>Copy as TypeScript</strong> matches against the catalog as it is now rather than as it was when you connected.</p><p>Which mapping applies on a given page is resolved automatically (patterns are checked in order, first match wins). The popup&#39;s <strong>Active project</strong> select shows the auto-resolved project for the current tab and lets you override it for that tab only — useful when two mappings could apply, or none do. The override is session-only (<code>chrome.storage.session</code>) and resets to automatic resolution when you pick <strong>Auto</strong> again or close the browser.</p><p><strong>A recording itself is never sent to your instance.</strong> Connecting only changes what the <strong>Copy as TypeScript</strong> export looks like (it can now use your own functions) and what the HUD shows while recording (ranked matches). Sending a recording to a server for anything beyond that — saving it, running codegen server-side — isn&#39;t implemented; if it is later, it will be opt-in per recording with a payload preview before the first send, matching the standard this extension already holds itself to for the API key.</p><p>The function catalog itself is managed from a project&#39;s <strong>Test functions</strong> page in the dashboard — add entries by hand, or paste a page-object method/helper&#39;s source code and let AI propose the name, parameters, and DOM pattern (a review form you edit before saving). With <a href="./ai-diagnosis.html">AI</a> configured on the instance, an <strong>Extract</strong> button calls it directly. Without one — or if you&#39;d rather use your own — <strong>Copy prompt for your own AI</strong> copies the full extraction prompt (rules, JSON schema, and your pasted code) for pasting into any AI chat (ChatGPT, Claude.ai, an IDE assistant, …); paste its reply back into the form below it and it&#39;s validated against the exact same schema, no Piwi AI credits spent either way. An MCP-connected coding agent (Claude Code, Cursor, …) can skip the copy-paste entirely and call the <code>create_test_function</code> <a href="./mcp.html">MCP tool</a> directly, using its own model to read the source. Registered entries can be edited in place from the same page — the pencil button reopens the form with everything filled in.</p><p>A parameter can be typed <strong>object</strong> for the options-bag argument most helpers take (<code>selectOption(page, { label }, { value })</code>), listing the bag&#39;s keys; a parameter source then targets one key by name, so generated calls pass <code>{ label: &#39;Country&#39; }</code> rather than a bare string. Extraction is deliberately conservative: a function that branches on its arguments, loops, or calls other helpers whose source isn&#39;t visible can&#39;t be captured as one fixed pattern, so it comes back with low confidence and a note saying what was left out, rather than a confident-looking guess.</p><p>Once a function is registered, use <strong>Test functions</strong> in the extension popup to check whether its pattern actually matches whatever page you&#39;re looking at.</p><h2 id="current-limits" tabindex="-1">Current limits <a class="header-anchor" href="#current-limits" aria-label="Permalink to &quot;Current limits&quot;">​</a></h2><ul><li><strong>One frame at a time.</strong> Picking inside an iframe, or across shadow DOM boundaries, isn&#39;t supported yet — the picker sees the top-level document. The same limit applies to recording.</li><li><strong>Recording covers one origin.</strong> The host permission recording requests is scoped to the site you started on; navigating to a different origin mid-recording stops capturing new steps there (nothing is lost — stop and review what was captured, or start a fresh recording on the new site). Expanding a running recording to a second origin isn&#39;t implemented yet.</li><li><strong>No aria-snapshot copier yet.</strong> Reproducing Playwright&#39;s <code>toMatchAriaSnapshot()</code> YAML format exactly needs the browser&#39;s real computed accessibility tree, which isn&#39;t reachable from a content script without a much heavier permission (<code>debugger</code>) than this extension asks for. An approximated version risks copying YAML that looks right but doesn&#39;t actually match — worse than not offering it. The copy-context-for-agent element summary is deliberately a simpler, non-recursive approximation instead (tag/role/name/attributes/text) rather than the same aria-snapshot format — fine for giving an AI agent context, not meant for a <code>toMatchAriaSnapshot()</code> assertion.</li><li><strong>Live re-check covers the common shapes.</strong> <code>getByTestId</code>, CSS locators, and a bare <code>getByRole</code> are re-verified against the page as it is now; text/label/placeholder-based matches and anchor-scoped chains keep the count captured at pick time (Playwright&#39;s own text-matching rules aren&#39;t reproduced here).</li><li><strong>Function matching is deterministic, not AI-assisted, in this phase.</strong> The catalog matcher scores DOM patterns against recorded steps; there&#39;s no optional AI pass yet to name things or break ties beyond the scoring itself.</li></ul><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p><code>apps/extension/</code> in the <a href="https://github.com/PiwiTests/platform" target="_blank" rel="noreferrer">monorepo</a> — see <a href="https://github.com/PiwiTests/platform/blob/main/apps/extension/AGENTS.md" target="_blank" rel="noreferrer"><code>apps/extension/AGENTS.md</code></a> for how it&#39;s built and tested.</p>`,31)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
